package jobs

import (
	"errors"
	"strings"
	"testing"
)

func TestSafeCause(t *testing.T) {
	tests := []struct {
		name     string
		err      error
		want     string   // exact output when non-empty
		contains []string // substrings that must be present
		absent   []string // substrings that must be gone
	}{
		{name: "nil error", err: nil, want: ""},
		{name: "plain text unchanged", err: errors.New("Repository not found."), want: "Repository not found."},
		{name: "text with a colon and no URL unchanged", err: errors.New("fatal: could not read Username: terminal prompts disabled"),
			want: "fatal: could not read Username: terminal prompts disabled"},
		{
			name:     "user and password",
			err:      errors.New("fatal: unable to access 'REDACTED': 403"),
			contains: []string{"https://gitlab.example/g/app.git/", "403"},
			absent:   []string{"glpat-abc", "oauth2:", "@gitlab"},
		},
		{name: "user only", err: errors.New("https://user@host/x"), want: "https://host/x"},
		{name: "ssh scheme", err: errors.New("ssh://git@host:22/x"), want: "ssh://host:22/x"},
		{name: "scp form has no secret", err: errors.New("git@github.com:o/r.git"), want: "git@github.com:o/r.git"},
		{
			name:     "private_token query value",
			err:      errors.New("GET https://h/api/v4/groups?private_token=REDACTED&page=2: 401"),
			contains: []string{"page=2", "401"},
			absent:   []string{"abc"},
		},
		{
			name:     "token query value",
			err:      errors.New("GET https://h/x?token=abc123&page=2: 401"),
			contains: []string{"page=2"},
			absent:   []string{"abc123"},
		},
		{
			name:     "access_token query value",
			err:      errors.New("GET https://h/x?page=2&access_token=REDACTED 401"),
			contains: []string{"page=2"},
			absent:   []string{"abc123"},
		},
		{
			name:     "query key is case-insensitive",
			err:      errors.New("GET https://h/x?PRIVATE_TOKEN=REDACTED&page=2: 401"),
			contains: []string{"page=2"},
			absent:   []string{"abc123"},
		},
		{
			name:     "several URLs in one message",
			err:      errors.New("clone REDACTED then REDACTED failed"),
			contains: []string{"one.example/x.git", "two.example/y.git", "failed"},
			absent:   []string{"s1", "s2", "s3", "a:", "b:"},
		},
		{
			name:     "wrapped error",
			err:      errors.Join(errors.New("walk"), errors.New("REDACTED")),
			contains: []string{"walk", "https://h/x"},
			absent:   []string{"REDACTED"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := SafeCause(tt.err)
			if tt.want != "" || tt.err == nil || len(tt.contains) == 0 {
				if got != tt.want {
					t.Fatalf("SafeCause = %q, want %q", got, tt.want)
				}
			}
			for _, s := range tt.contains {
				if !strings.Contains(got, s) {
					t.Errorf("SafeCause = %q, want it to contain %q", got, s)
				}
			}
			for _, s := range tt.absent {
				if strings.Contains(got, s) {
					t.Errorf("SafeCause = %q, must not contain %q", got, s)
				}
			}
		})
	}
}
package explorer

import "github.com/anthnel/devdesk/internal/jobs"

// What each clone event tells the registry (jobs.Reporter).
//
// The mapping lives here and not in the router, for the reason Reporter exists:
// "a repository that was already on disk is a skip, and it is not news" is this
// package's vocabulary, and a router that knew it would grow a branch per view.
//
// cloneFound and cloneWalkFailed both set Discover, because both name a target
// the run has never heard of — the walk is what finds them (D3). The others
// address a row that exists.

func (m CloneEventMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindClone, Target: m.event.path}
	switch m.event.kind {
	case cloneFound:
		t.State, t.Discover = jobs.ItemQueued, true
	case cloneBegan:
		t.State = jobs.ItemRunning
	case cloneEnded:
		switch {
		case m.event.err != nil:
			t.State, t.Detail = jobs.ItemFailed, m.event.err.Error()
		case m.event.skipped:
			// Not a failure and not work: the directory was already there, and
			// decision 2 says the explorer leaves what exists alone.
			t.State = jobs.ItemSkipped
		default:
			t.State = jobs.ItemDone
		}
	case cloneWalkFailed:
		// A group that could not be listed gets a row of its own rather than
		// being folded into a repository's error: the repositories under it
		// were never discovered, so no other row can stand for them. It is
		// discovered *as* a failure — there was never a queued state for it.
		t.State, t.Detail, t.Discover = jobs.ItemFailed, "discovery: "+m.event.err.Error(), true
	}
	return t
}

// Seal says the walk is over (jobs.Sealer). Until it is called the run is
// unsettled whatever its rows say: a walk that has found three repositories and
// cloned all three is not done.
func (CloneRunFinishedMsg) Seal() jobs.Kind { return jobs.KindClone }

// Compile-time proof that the two messages carry what the registry needs. One
// added without it would be routed, would update the view, and would leave its
// row spinning for the life of the screen.
var (
	_ jobs.Reporter = CloneEventMsg{}
	_ jobs.Sealer   = CloneRunFinishedMsg{}
)
	}
	return a, a.jobsChanged()
}

// handleForgeIndexBuilt settles the job whatever the generation — the run is
// in the registry either way — and installs the index only for the session
// that asked for it.
func (a *App) handleForgeIndexBuilt(msg forgeIndexBuiltMsg) (tea.Model, tea.Cmd) {
	t := jobs.Transition{Kind: jobs.KindIndex, Target: msg.target, State: jobs.ItemDone}
	switch {
	case errors.Is(msg.err, context.Canceled):
		t.State, t.Detail = jobs.ItemSkipped, "cancelled"
	case msg.err != nil:
		log.Printf("ERROR [app/forge-index] walk: %v", msg.err)
		t.State, t.Detail = jobs.ItemFailed, msg.err.Error()
	case msg.index.Skipped() > 0:
		t.Detail = components.Plural(msg.index.Skipped(), "namespace", "namespaces") + " could not be listed"
	}

	var cmds []tea.Cmd
	if a.jobs.Apply(t) {
		cmds = append(cmds, a.jobsChanged())
	}
	if msg.gen == a.forgeIndexGen {
		a.forgeIndexCancel = nil
		pending := a.forgeIndexPending
