package jobs

import (
	"regexp"
	"strings"
)

var (
	// userinfo between "scheme://" and the host: everything up to the "@".
	urlUserinfo = regexp.MustCompile(`(?i)\b((?:https?|ssh)://)[^\s/@'"]+@`)
	// the value of a token-bearing query parameter.
	tokenParam = regexp.MustCompile(`(?i)\b((?:private_|access_)?token=)[^&\s'"]*`)
)

// SafeCause renders an error for display and logs with the credentials a URL
// in its text may carry removed: userinfo of http(s) and ssh:// URLs and the
// values of token query parameters. The scp form (git@host:path) carries no
// secret and is left alone.
func SafeCause(err error) string {
	if err == nil {
		return ""
	}
	s := urlUserinfo.ReplaceAllString(err.Error(), "$1")
	return tokenParam.ReplaceAllString(s, "${1}"+strings.Repeat("*", 0))
}
EOF
